def solve(n, edges, s, t):
    from collections import deque

    # If source and target are the same, return 0
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm for shortest path in a graph with negative weights
    # (though in this case, all weights are non-negative, so Dijkstra would also work)
    # However, Bellman-Ford is easier to implement and handles negative weights too

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if target is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
